def transform(grid):
    n = len(grid)
    out = [[0] * (n * n) for _ in range(n * n)]
    for r in range(n):
        for c in range(n):
            color = grid[r][c]
            if color != 0:
                for i in range(n):
                    for j in range(n):
                        if grid[i][j] == 0:
                            out[r*n+i][c*n+j] = color
    return out
